INSERT INTO market_translation (market_id, locale, description) VALUES
    ('0d3a731b-7c65-5d1b-bd0f-eb7508dedace', 'de', 'Frisches Obst und Gemüse, türkische und arabische Spezialitäten – seit Jahren mitten in St. Georg.'),
    ('0d3a731b-7c65-5d1b-bd0f-eb7508dedace', 'en', 'Fresh produce plus Turkish and Arabic specialities in the heart of St. Georg.'),
    ('0d3a731b-7c65-5d1b-bd0f-eb7508dedace', 'ar', 'فواكه وخضروات طازجة وتخصصات تركية وعربية في قلب حي سانت غيورغ.'),
    ('e6c9e9f5-c4bc-567b-a04b-e5bcdffcbb9b', 'de', 'Levantinische Feinkost: Za''atar, Labneh, Maamoul und Kaffee mit Kardamom.'),
    ('e6c9e9f5-c4bc-567b-a04b-e5bcdffcbb9b', 'en', 'Levantine delicatessen: za''atar, labneh, maamoul and cardamom coffee.'),
    ('e6c9e9f5-c4bc-567b-a04b-e5bcdffcbb9b', 'ar', 'أطعمة شامية فاخرة: زعتر ولبنة ومعمول وقهوة بالهيل.'),
    ('535406e6-543f-5309-bba4-fac75c629d37', 'de', 'Gewürze, Linsen, Basmati und frisches Gemüse für die indische Küche.'),
    ('535406e6-543f-5309-bba4-fac75c629d37', 'en', 'Spices, lentils, basmati and fresh vegetables for Indian home cooking.'),
    ('535406e6-543f-5309-bba4-fac75c629d37', 'ar', 'بهارات وعدس وأرز بسمتي وخضار طازجة للمطبخ الهندي.'),
    ('46554c65-3563-5d82-9f53-c18d1477abc0', 'de', 'Nudeln, Saucen, Tiefkühl-Dumplings und frisches Pak Choi aus ganz Asien.'),
    ('46554c65-3563-5d82-9f53-c18d1477abc0', 'en', 'Noodles, sauces, frozen dumplings and fresh pak choi from all over Asia.'),
    ('46554c65-3563-5d82-9f53-c18d1477abc0', 'ar', 'نودلز وصلصات وزلابية مجمدة وبوك تشوي طازج من كل أنحاء آسيا.'),
    ('647ab58a-f064-59e2-b5c7-883cbe54087e', 'de', 'Polnische Klassiker: Pierogi, Twaróg, Kabanos und frisches Roggenbrot.'),
    ('647ab58a-f064-59e2-b5c7-883cbe54087e', 'en', 'Polish classics: pierogi, twaróg, kabanos and fresh rye bread.'),
    ('647ab58a-f064-59e2-b5c7-883cbe54087e', 'ar', 'أطباق بولندية كلاسيكية: بيروغي وجبن تفاروغ وكابانوس وخبز الجاودار الطازج.'),
    ('ae1232c0-0ff2-5eb2-9b7c-0ec9a20dd70c', 'de', 'Handwerksbäckerei mit Natursauerteig und den besten Franzbrötchen in Ottensen.'),
    ('ae1232c0-0ff2-5eb2-9b7c-0ec9a20dd70c', 'en', 'Craft bakery with natural sourdough and the best Franzbrötchen in Ottensen.'),
    ('ae1232c0-0ff2-5eb2-9b7c-0ec9a20dd70c', 'ar', 'مخبز حرفي بالعجين المخمر الطبيعي وأشهى فرانزبروتشن في حي أوتنزن.'),
    ('37637a3c-3e95-5b60-9d5e-c19bebfa1ed9', 'de', 'Halal-Fleisch vom Meister: Lamm, Rind und Geflügel, frisch zugeschnitten.'),
    ('37637a3c-3e95-5b60-9d5e-c19bebfa1ed9', 'en', 'Halal meat from a master butcher: lamb, beef and poultry, freshly cut.'),
    ('37637a3c-3e95-5b60-9d5e-c19bebfa1ed9', 'ar', 'لحوم حلال من جزار محترف: غنم وبقر ودواجن مقطعة طازجة.'),
    ('99b67bdb-4b76-53f6-bbed-803c3584cd6b', 'de', 'Bio-Obst und -Gemüse aus der Region, dazu Naturkost für jeden Tag.'),
    ('99b67bdb-4b76-53f6-bbed-803c3584cd6b', 'en', 'Organic regional fruit and vegetables plus everyday natural foods.'),
    ('99b67bdb-4b76-53f6-bbed-803c3584cd6b', 'ar', 'فواكه وخضروات عضوية من المنطقة وأغذية طبيعية لكل يوم.'),
    ('624ca619-8a16-5c4e-9389-e03fa16aa824', 'de', 'Unser Stand auf dem Wochenmarkt: Gemüse, Eier und Honig direkt vom Hof.'),
    ('624ca619-8a16-5c4e-9389-e03fa16aa824', 'en', 'Our weekly market stall: vegetables, eggs and honey straight from the farm.'),
    ('624ca619-8a16-5c4e-9389-e03fa16aa824', 'ar', 'بسطتنا في السوق الأسبوعي: خضار وبيض وعسل مباشرة من المزرعة.'),
    ('f4d5579a-aad0-57e2-81a9-e589884bec39', 'de', 'Wasser, Säfte und Kisten – wir liefern bis an die Wohnungstür.'),
    ('f4d5579a-aad0-57e2-81a9-e589884bec39', 'en', 'Water, juices and crates – delivered to your door.'),
    ('f4d5579a-aad0-57e2-81a9-e589884bec39', 'ar', 'مياه وعصائر وصناديق مشروبات – نوصلها حتى باب منزلكم.'),
    ('80760aae-eeb4-56e9-b44c-c880b2209382', 'de', 'Der Vollsortimenter in Barmbek: frisch, günstig und lange geöffnet.'),
    ('80760aae-eeb4-56e9-b44c-c880b2209382', 'en', 'Barmbek''s full-range supermarket: fresh, good value and open late.'),
    ('80760aae-eeb4-56e9-b44c-c880b2209382', 'ar', 'سوبرماركت متكامل في بارمبيك: طازج وبأسعار مناسبة ومفتوح حتى وقت متأخر.'),
    ('c4a94fd2-c0fd-5d87-8166-7fb5331102d1', 'de', 'Westafrikanische Zutaten: Yams, Kochbananen, Gari, Shito und Bissap.'),
    ('c4a94fd2-c0fd-5d87-8166-7fb5331102d1', 'en', 'West African staples: yam, plantain, gari, shito and bissap.'),
    ('c4a94fd2-c0fd-5d87-8166-7fb5331102d1', 'ar', 'مكونات من غرب أفريقيا: يام وموز الطبخ وغاري وصلصة شيتو والكركديه.');
