-- Invented Hamburg demo data: 12 markets, a shared catalog with de/en/ar translations, listings,
-- banners and promotions. Market names, street names, brands and people are fictitious.
-- Timestamps are relative to now() so that "new" listings and promotions stay current.
-- catalog_product.search_text / catalog_product_translation.search_name are filled at startup
-- by the application (SearchTextIndexer) with the same normaliser that the search uses.









-- Price history starts with the current price.
SELECT md5('price:' || mp.id::text)::uuid, mp.id, mp.price_cents, mp.created_at, NULL FROM market_product mp;





